    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00042",
          "explanation": "医生用通俗语言解释视网膜动脉阻塞，并把计划压缩为优先事项。",
          "quote": "就是你们说的“眼底血管堵了”"
        }
